'use strict';

// MODULES //

var isSignalReference = require( '@stdlib/plot/vega/base/assert/is-signal-reference' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var signalName = require( './../../utils/signal_name.js' );


// VARIABLES //

var PROPS = [
	'background'
];


// MAIN //

/**
* Returns a transformed schema containing signals for use in conjunction with UI components.
*
* ## Notes
*
* -   The function mutates both the input schema and the provided list of signals.
*
* @private
* @param {Object} schema - schema
* @param {Array} signals - list of signals
* @param {Object} defaults - schema defaults
* @returns {Object} transformed schema
*/
function transform( schema, signals, defaults ) {
	var name;
	var out;
	var k;
	var v;
	var i;

	out = schema;
	for ( i = 0; i < PROPS.length; i++ ) {
		k = PROPS[ i ];
		v = schema[ k ];
		if ( !isSignalReference( v ) ) {
			name = signalName( k );
			signals.push({
				'name': name,
				'value': ( isUndefined( v ) ) ? defaults[ k ].default : v
			});
			out[ k ] = {
				'signal': name
			};
		}
	}
	return out;
}


// EXPORTS //

module.exports = transform;
